const hex=b=>b.toString(16).toUpperCase().padStart(2,'0');
export function communicationCSV(i2c=[],other=[]){const rows=[...other,...i2c.map(t=>({cycle:t.cycle,bus:'I2C',device:'0x'+hex(t.address),status:(t.write?'W':'R')+' '+(t.ack?(t.dataACK?'ACK':'DATA NACK'):'NACK')+' '+Math.round(t.frequency/1000)+'kHz',data:t.data.map(hex).join(' ')}))].sort((a,b)=>a.cycle-b.cycle);const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';return 'cycle,time_ms,bus,device,status,data\r\n'+rows.map(t=>[t.cycle,(t.cycle/16000).toFixed(6),t.bus,t.device,t.status,t.data].map(quote).join(',')).join('\r\n');}
